{
  "arguments": [
    {
      "id": "G1",
      "name": "Volume 4 is not an abandonment of resurrection apologetics",
      "speaker": "Gary Habermas",
      "conclusion": "Volume 4's focus on theological and practical implications does not mean Habermas has given up on evidential resurrection apologetics.",
      "premises": [
        "P1 The book has two halves: the first half treats God, miracles, and worldview; the second half is almost no apologetics by his definition.",
        "P2 Resurrection apologetics still appears here and there, but it is not the concentration of the volume.",
        "P3 The series is built on the evidential case of volume 1 and the reputational/historical case of volume 2, without which volume 4 could not be done at a scholarly level.",
        "P4 Habermas has always been a strict evidentialist and would not do subjective or presuppositionalist apologetics even if paid."
      ],
      "strength": {
        "st1": {
          "v": 2,
          "quote": "And as far as he's uh going on faith and presuppositionalism, a total total joke."
        },
        "st2": {
          "v": 2,
          "quote": "The second half of the book is almost no apologetics by my uh definition."
        },
        "st3": {
          "v": 2,
          "quote": "The resurrection argument stands on a evidences volume one, b reputations volume two."
        },
        "st4": {
          "v": 2,
          "quote": "You may not like my reasons, but don't say I'm not giving reasons."
        },
        "st5": {
          "v": 2,
          "quote": "They said, well, see, this is Gary admitting that the evidence for the resurrection is no good."
        },
        "st6": {
          "v": 2,
          "quote": "Resurrection apologetics is going to come up here and there, but it's not anything I concentrate on so much."
        },
        "st7": {
          "v": 0,
          "quote": ""
        },
        "st8": {
          "v": 2,
          "quote": "I've known Gary for what 16 years now, 16 years plus, and he he's always been hardcore strict evidentialism"
        }
      },
      "prior_art": "Gary Habermas, The Historical Jesus (1984/1996) and The Risen Jesus and Future Hope (2003)",
      "originality": {
        "or1": {
          "v": 2,
          "quote": "The second half of the book is almost no apologetics by my uh definition.",
          "why": "This is a self-referential defense of the structure of a new volume, not a restatement of a prior apologetic argument."
        },
        "or2": {
          "v": 2,
          "quote": "The resurrection argument stands on a evidences volume one, b reputations volume two.",
          "why": "It uses the four-volume series architecture itself as evidence about Habermas's intent."
        },
        "or3": {
          "v": 0,
          "quote": "",
          "why": "No cross-domain connection is made."
        },
        "or4": {
          "v": 0,
          "quote": "",
          "why": "No formalization, equation, or model is added."
        }
      },
      "weakest_link": "P4 (Habermas's lifelong evidentialism) is supported mainly by his own and his host's testimony, not by independent evidence.",
      "develop_next": "Quote the actual text of volume 4's two halves and volume 1/2 dependence to show the structural claim is checkable.",
      "case_map": [],
      "domain": "philosophy"
    },
    {
      "id": "G2",
      "name": "Skeptical objections are unfalsifiable and silly",
      "speaker": "Gary Habermas",
      "conclusion": "The objection that volume 4 abandons evidence is not worth answering because radical skeptics will never be satisfied.",
      "premises": [
        "P1 If skeptics are really skeptical, no answer will make a difference; they will move to another objection or invent a new story.",
        "P2 The objection itself is absurd because Habermas continues to give reasons and evidence.",
        "P3 The critics ignore volumes 1 and 2, which still stand as the evidential foundation."
      ],
      "strength": {
        "st1": {
          "v": 2,
          "quote": "But I'm just saying those objections are absolutely silly."
        },
        "st2": {
          "v": 2,
          "quote": "If they're really skeptical, no matter what I say will make no difference."
        },
        "st3": {
          "v": 1,
          "quote": "It's almost like they're pretending oh so volume one and two have just vanished or or something"
        },
        "st4": {
          "v": 1,
          "quote": "You may not like my reasons, but don't say I'm not giving reasons."
        },
        "st5": {
          "v": 1,
          "quote": "They said, well, see, this is Gary admitting that the evidence for the resurrection is no good."
        },
        "st6": {
          "v": 1,
          "quote": "You can't really answer these guys because here's the key."
        },
        "st7": {
          "v": 0,
          "quote": ""
        },
        "st8": {
          "v": 1,
          "quote": "I've had to go through volume volume four and that sort of thing."
        }
      },
      "prior_art": "None known",
      "originality": {
        "or1": {
          "v": 2,
          "quote": "But I'm just saying those objections are absolutely silly.",
          "why": "It is a meta-level dismissal of critics, not a restatement of a prior apologetic argument."
        },
        "or2": {
          "v": 2,
          "quote": "It's almost like they're pretending oh so volume one and two have just vanished",
          "why": "It uses the continued existence of volumes 1 and 2 as the counter-evidence."
        },
        "or3": {
          "v": 0,
          "quote": "",
          "why": "No cross-domain connection is made."
        },
        "or4": {
          "v": 0,
          "quote": "",
          "why": "No formalization is added."
        }
      },
      "weakest_link": "P1 (radical skeptics are never satisfied) is an unfalsifiable generalization about critics' psychology.",
      "develop_next": "Give a testable criterion distinguishing a good-faith objection from a radical-skeptic one.",
      "case_map": [],
      "domain": "philosophy"
    },
    {
      "id": "G3",
      "name": "Theism and afterlife are linked",
      "speaker": "Gary Habermas",
      "conclusion": "An evidential afterlife case is a strong argument for God because an afterlife cannot be explained by naturalism.",
      "premises": [
        "P1 Russell's Why I Am Not a Christian treats God and the afterlife as the two things needed for theism.",
        "P2 If there is an afterlife, one must ask why; it does not follow from any naturalism Habermas knows.",
        "P3 An afterlife cannot come from time plus chance plus the natural world.",
        "P4 Therefore an afterlife points to a God who is needed for it."
      ],
      "strength": {
        "st1": {
          "v": 2,
          "quote": "So, that's why I did afterlife because I think it's probably not a not as strong for God."
        },
        "st2": {
          "v": 2,
          "quote": "Um, I don't think that follows from any naturalism I know."
        },
        "st3": {
          "v": 1,
          "quote": "in that short pretty short book, uh we learn that what you need for theism is God in the afterlife."
        },
        "st4": {
          "v": 1,
          "quote": "I don't think an afterlife comes from God plus chance [snorts] plus the supernatural just just to I mean, sorry, time plus chance plus the the natural world."
        },
        "st5": {
          "v": 1,
          "quote": "So, now you got to ask, if God raised him from the dead, why why did God raise him from the dead?"
        },
        "st6": {
          "v": 1,
          "quote": "I think it's a strong argument, but I think it's once you have an afterlife, you've got to ask why."
        },
        "st7": {
          "v": 0,
          "quote": ""
        },
        "st8": {
          "v": 1,
          "quote": "It's like the ethical argument, you know, why why do why do objective ethics u come in a chance big bang?"
        }
      },
      "prior_art": "Bertrand Russell, Why I Am Not a Christian, 1927",
      "originality": {
        "or1": {
          "v": 1,
          "quote": "in that short pretty short book, uh we learn that what you need for theism is God in the afterlife.",
          "why": "It is a variant of Russell's framework inverted into a positive argument."
        },
        "or2": {
          "v": 1,
          "quote": "I think if you have an evidential afterlife case, and I think we do uh sort of like intelligent design or fine-tuning",
          "why": "It brings near-death and related afterlife evidence, though only by mention."
        },
        "or3": {
          "v": 1,
          "quote": "It's like the ethical argument, you know, why why do why do objective ethics u come in a chance big bang?",
          "why": "It links afterlife to the moral argument and big-bang cosmology."
        },
        "or4": {
          "v": 0,
          "quote": "",
          "why": "No formalization is added."
        }
      },
      "weakest_link": "P3 (an afterlife cannot come from time + chance + nature) is asserted, not argued.",
      "develop_next": "Provide the actual evidential afterlife case (NDEs, etc.) rather than gesturing at it.",
      "case_map": ["K13"],
      "domain": "philosophy"
    },
    {
      "id": "G4",
      "name": "Resurrection entails God and the deity of Christ",
      "speaker": "Gary Habermas",
      "conclusion": "If the resurrection occurred, it entails a God who raised Jesus and links to Jesus' unique claims, including his deity.",
      "premises": [
        "P1 If there is a resurrection, there must be a God who did it.",
        "P2 No founder of the major world religions was reportedly raised from the dead, nor were Old Testament figures such as Moses, Daniel, or David.",
        "P3 Jesus' leading teaching was the kingdom of God and how to enter it, and he claimed to hold the keys to it.",
        "P4 God would not raise a false teacher from the dead, so Jesus' major teaching must be true.",
        "P5 Jesus' ethical life and claims further support the link to his deity."
      ],
      "strength": {
        "st1": {
          "v": 2,
          "quote": "If there's a resurrection, I think there's a God."
        },
        "st2": {
          "v": 2,
          "quote": "God doesn't wouldn't raise a heretic from the dead."
        },
        "st3": {
          "v": 1,
          "quote": "Moses didn't rise from the dead. Daniel didn't rise from the dead. David didn't rise from the dead."
        },
        "st4": {
          "v": 1,
          "quote": "If pre if he preached good e ethics and yet his major teaching the kingdom of God how to get there was false. seems to me that the major the falseness of the major rules out the truth the truth of the minor."
        },
        "st5": {
          "v": 1,
          "quote": "Now, why Jesus? Why not these other people? Why not the founders of any of the world major religion?"
        },
        "st6": {
          "v": 1,
          "quote": "I think backdoor if you've got a resurrection, you could argue back to who did it."
        },
        "st7": {
          "v": 0,
          "quote": ""
        },
        "st8": {
          "v": 2,
          "quote": "Even critical scholars, Dale Allison, I mean others, uh, they think it's likely that Jesus foretold his death and resurrection ahead of time."
        }
      },
      "prior_art": "Gary Habermas, The Risen Jesus and Future Hope, 2003; William Lane Craig, Assessing the New Testament Evidence for the Historicity of the Resurrection of Jesus, 1989",
      "originality": {
        "or1": {
          "v": 1,
          "quote": "If there's a resurrection, I think there's a God.",
          "why": "It is a variant of the standard resurrection-to-God inference, extended to the deity of Christ."
        },
        "or2": {
          "v": 2,
          "quote": "Even critical scholars, Dale Allison, I mean others, uh, they think it's likely that Jesus foretold his death and resurrection ahead of time.",
          "why": "It brings critical-scholarship support for Jesus' prediction of his resurrection."
        },
        "or3": {
          "v": 1,
          "quote": "God doesn't wouldn't raise a heretic from the dead.",
          "why": "It connects resurrection to the moral argument and God's omnibenevolence."
        },
        "or4": {
          "v": 0,
          "quote": "",
          "why": "No formalization is added."
        }
      },
      "weakest_link": "P4 (God would not raise a false teacher) is a theological intuition that needs defense against counterexamples.",
      "develop_next": "Show from the Gospels that Jesus' kingdom claims were central and that he staked his credibility on them.",
      "case_map": ["K16", "K13"],
      "domain": "theology"
    },
    {
      "id": "G5",
      "name": "Scripture is entailed by the resurrection",
      "speaker": "Gary Habermas",
      "conclusion": "Scripture is entailed by the resurrection, though further down the line than the kingdom and ethics.",
      "premises": [
        "P1 If Jesus is Lord and was raised, his view of Scripture ought to be obeyed.",
        "P2 Jesus' two greatest commandments concern loving God and loving others, and Scripture follows from accepting his teaching.",
        "P3 God did not raise Jesus merely to affirm a view of the Bible, but Scripture is still entailed somewhere down the line."
      ],
      "strength": {
        "st1": {
          "v": 2,
          "quote": "I think scriptures entailed somewhere down the line, just like I think ethics are entailed somewhere down the line."
        },
        "st2": {
          "v": 2,
          "quote": "If he is our Lord that's a New Testament view I think if Jesus is our Lord then we should take his view on things."
        },
        "st3": {
          "v": 1,
          "quote": "Galatians chapter 6, Paul says, and this this sounds like a little bit with a down a downsizing of the good Samaritan."
        },
        "st4": {
          "v": 1,
          "quote": "Jesus only numbers the two greatest theological doctrines in Luke 10."
        },
        "st5": {
          "v": 1,
          "quote": "I think a lot of these things come from resurrection."
        },
        "st6": {
          "v": 1,
          "quote": "I don't think God raised him from the dead to say uh Jesus loves me this I know for the Bible tells me so."
        },
        "st7": {
          "v": 0,
          "quote": ""
        },
        "st8": {
          "v": 1,
          "quote": "Now, somebody could say, I suppose, I've thought about this a lot. Yeah, he didn't say where they were the two most important overall."
        }
      },
      "prior_art": "None known",
      "originality": {
        "or1": {
          "v": 2,
          "quote": "I think scriptures entailed somewhere down the line, just like I think ethics are entailed somewhere down the line.",
          "why": "It is a new ordering of entailments from the resurrection, placing Scripture below kingdom and ethics."
        },
        "or2": {
          "v": 1,
          "quote": "Galatians chapter 6, Paul says, and this this sounds like a little bit with a down a downsizing of the good Samaritan.",
          "why": "It brings Galatians 6 and Luke 10 into the entailment argument."
        },
        "or3": {
          "v": 1,
          "quote": "Jesus only numbers the two greatest theological doctrines in Luke 10.",
          "why": "It connects the resurrection to a hierarchy of theological doctrines via the two greatest commandments."
        },
        "or4": {
          "v": 0,
          "quote": "",
          "why": "No formalization is added."
        }
      },
      "weakest_link": "P2 (Scripture follows from accepting Jesus' teaching) is asserted without showing Jesus' own view of Scripture.",
      "develop_next": "Cite Jesus' explicit statements about Scripture (e.g., Matthew 5:17-18) to ground the entailment.",
      "case_map": ["K16"],
      "domain": "theology"
    },
    {
      "id": "G6",
      "name": "Criteria for identifying a miracle",
      "speaker": "Gary Habermas",
      "conclusion": "A miracle is best identified as a one-time event, performed by God, with very good evidence, serving as a sign to authenticate a message.",
      "premises": [
        "P1 A miracle is an act of God or an invisible agent, and by Christian standards such an agent is God or God's creation.",
        "P2 Jesus taught that miracles are signs pointing to a truth, and he tied himself to that teaching.",
        "P3 Richard Swinburne's definition is preferable: a miracle at its best is a one-time event with very good evidence, for the purpose of evidencing a message.",
        "P4 Repeated events under known circumstances, such as alleged levitation, are not first-rate miracles.",
        "P5 The resurrection fits this criterion uniquely because it is unrepeatable and was predicted ahead of time."
      ],
      "strength": {
        "st1": {
          "v": 2,
          "quote": "I like Richard Swinsburn's definition that a miracle it's it at its best it's a one-time event where the evidence is very good."
        },
        "st2": {
          "v": 2,
          "quote": "a miracle is an act of God or an invisible agent."
        },
        "st3": {
          "v": 2,
          "quote": "I think he's right when he says if something is repeated under certain circumstances chances are that's not a miracle or if it is it's not a first rate miracle"
        },
        "st4": {
          "v": 2,
          "quote": "I think the resurrection is a great connection between look it's never happened before."
        },
        "st5": {
          "v": 2,
          "quote": "some people say things like Richard Swinburn I think is a goes a little too far here"
        },
        "st6": {
          "v": 2,
          "quote": "Virtually everybody, unless they're prepared to be accosted uh factually, almost everybody thinks that the resurrection fits that criteria like no other potential thing."
        },
        "st7": {
          "v": 1,
          "quote": "when Indian gurus are often said to have levitated a bit and maybe they don't do it all the time maybe they do it sometimes but it's done over and over again or certain circumstances, I say, \"Yeah, that's a really weird event. I wouldn't mind knowing how that's done, but I don't think it's a miracle.\""
        },
        "st8": {
          "v": 2,
          "quote": "I think there's a number of them, but I think the resurrection is the key one that's puts the glue in there, the cement between the bricks, if you will."
        }
      },
      "prior_art": "Richard Swinburne, The Concept of Miracle, 1970; David Hume, Of Miracles, 1748; C.S. Lewis, Miracles, 1947",
      "originality": {
        "or1": {
          "v": 1,
          "quote": "I like Richard Swinsburn's definition that a miracle it's it at its best it's a one-time event where the evidence is very good.",
          "why": "It adopts Swinburne's definition and applies it to the resurrection."
        },
        "or2": {
          "v": 2,
          "quote": "Even critical scholars, Dale Allison, I mean others, uh, they think it's likely that Jesus foretold his death and resurrection ahead of time.",
          "why": "It brings the prediction of the resurrection as additional evidence beyond the event itself."
        },
        "or3": {
          "v": 1,
          "quote": "I think that's Jesus's point in in Mark chapter 2 when the guy comes through the roof and Jesus said, \"Your sins are forgiven.\"",
          "why": "It connects miracle criteria to Jesus' forgiveness healing as a sign."
        },
        "or4": {
          "v": 0,
          "quote": "",
          "why": "No formalization is added."
        }
      },
      "weakest_link": "P5 (the resurrection is unrepeatable and predicted) depends on the reliability of the prediction texts and on the uniqueness claim.",
      "develop_next": "Give the specific criteria and show how competing miracle claims fail each one.",
      "case_map": ["K16"],
      "domain": "philosophy"
    }
  ]
}
